  final intersection = set1.intersection(set2);

  if (intersection.length == 0 && 
      !(set1.isEmpty || set2.isEmpty)) return -1;

  double unionSize =
    max(min(intersection.length.toDouble(), set1.length),
         min(intersection.length.toDouble(),
             set2.length));

